// 传奇扑克牌手数据库 - 核心数据
export interface PlayerResult {
  year: number;
  location: string;
  eventName: string;
  buyIn: string;
  prize: string;
  placing: string;
  players: number;
}

export interface Player {
  id: string;
  name: string;
  country: string;
  flag: string;
  nickname?: string;
  image: string;
  totalEarnings: string;
  titles: number;
  cashes: number;
  bestCash: string;
  bio: string;
  tritonResults: PlayerResult[];
  otherSeries?: string[];
  tags: string[];
}

export interface Video {
  id: string;
  title: string;
  url: string;
  thumbnail: string;
  platform: 'youtube' | 'twitch' | 'pokertube' | 'other';
  duration: string;
  views: string;
  publishedAt: string;
  event?: string;
  players: string[];
  subtitles?: string;
  tags: string[];
  addedAt: string;
  isSaved: boolean;
}

export interface TournamentEvent {
  id: string;
  name: string;
  gameType: string;
  buyIn: string;
  entries: number;
  prizePool: string;
  date: string;
  status: 'completed' | 'upcoming';
  results: TournamentEventResult[];
}

export interface TournamentEventResult {
  placing: string;
  playerName: string;
  playerId?: string;        // link to Player.id if in our DB
  prize: string;
  country?: string;
  flag?: string;
  gpiRanking?: number;       // GPI global ranking
}

export interface Tournament {
  id: string;
  name: string;
  year: number;
  location: string;
  startDate: string;
  endDate: string;
  events: number;
  totalPrizePool: string;
  winner: string;
  imageUrl: string;
  description: string;
  eventList?: TournamentEvent[];  // detailed sub-events
  highlights?: string;            // tournament highlight text
  venue?: string;                 // casino/venue name
  gpiNote?: string;               // GPI reference note
}

